# ============================================================
# This was added by AI to ensure project root path is defined.
# I've typically just done relative paths in my code.
# ============================================================
def find_project_root() -> Path:
    """Find project root by locating secrets.env."""

    current = Path.cwd().resolve()

    for path in [current, *current.parents]:
        if (path / "secrets.env").is_file():
            return path

    raise FileNotFoundError("Could not locate secrets.env")


PROJECT_ROOT = find_project_root()

def resolve_path(value: str | None) -> Path | None:
    """Resolve a path value, expanding user and making absolute relative to project root."""

    if not value:
        return None

    path = Path(value).expanduser()

    if not path.is_absolute():
        path = PROJECT_ROOT / path

    return path.resolve()


