def load_env(env_path: str | None = None) -> None:
    """Load environment variables from secrets.env."""

    from dotenv import load_dotenv

    if env_path is None:
        env_path = PROJECT_ROOT / "secrets.env"

    load_dotenv(Path(env_path), override=True)


def get_env_list(variable: str) -> list[str]:
    """Get a comma-separated list from an environment variable."""

    return [
        item.strip()
        for item in os.getenv(variable, "").split(",")
        if item.strip()
    ]


def get_bool(variable: str, default: bool = False) -> bool:
    """Parse a boolean environment variable."""

    value = os.getenv(variable)

    if value is None:
        return default

    value = value.strip().lower()

    if value in ("true", "1", "yes", "on"):
        return True

    if value in ("false", "0", "no", "off"):
        return False

    raise ValueError(f"Invalid boolean value for {variable}: {value}")


def resolve_env_vars(value: Any) -> Any:
    """Resolve ${VAR_NAME} patterns in strings."""

    if isinstance(value, str):
        pattern = r"\$\{([^}]+)\}"

        def replacer(match):
            var_name = match.group(1)
            return os.getenv(var_name, match.group(0))

        return re.sub(pattern, replacer, value)

    if isinstance(value, dict):
        return {k: resolve_env_vars(v) for k, v in value.items()}

    if isinstance(value, list):
        return [resolve_env_vars(item) for item in value]

    return value


def load_task_config(task_file: str | None = None) -> dict:
    """Load and process tasks.json configuration."""

    import json

    if task_file is None:
        task_file = PROJECT_ROOT / "tasks.json"

    path = Path(task_file)

    if not path.is_file():
        raise FileNotFoundError(f"Task config not found: {path}")

    with open(path, "r") as f:
        config = json.load(f)

    return resolve_env_vars(config)


