def get_smtp_config() -> dict:
    """Build SMTP configuration from environment variables."""

    return {
        "smtp_host": os.getenv("SMTP_HOST"),
        "smtp_port": int(os.getenv("SMTP_PORT", "587")),
        "email_address": os.getenv("SMTP_EMAIL"),
        "email_password": os.getenv("SMTP_PASSWORD"),
        "smtp_auth": get_bool("SMTP_AUTH", True),
        "use_ssl": get_bool("SMTP_USE_SSL", False),
        "start_tls": get_bool("SMTP_START_TLS", True),
        "from_email": os.getenv("SMTP_EMAIL"),
    }

# ============================================================
# Had AI generate the pgp config pull and email recps on this one.
# Traditionally I have just done everything with PGP with
# a single target pub key to the same email. With the pgp keys
# stored as strings in my env file. 
# ============================================================
def get_pgp_config() -> dict:
    """Build PGP configuration from environment variables."""

    private_key_path = resolve_path(os.getenv("PGP_PRIVATE_KEY_PATH"))
    public_key_path = resolve_path(os.getenv("PGP_PUBLIC_KEY_PATH"))

    return {
        "pgp_enabled": get_bool("PGP_ENABLED", False),
        "pgp_sign": get_bool("PGP_SIGN_ENABLED", True),
        "pgp_encrypt": get_bool("PGP_ENCRYPT_ENABLED", True),
        "pgp_private_key_path": str(private_key_path) if private_key_path else None,
        "pgp_private_key_password": os.getenv("PGP_PRIVATE_KEY_PASSWORD"),
        "pgp_recipient_keys": [
            str(resolve_path(path))
            for path in get_env_list("PGP_RECIPIENT_KEYS")
        ],
    }


def get_email_recipients() -> dict:
    """Build email recipient configuration from environment variables."""

    return {
        "to": get_env_list("EMAIL_TO"),
        "cc": get_env_list("EMAIL_CC"),
        "bcc": get_env_list("EMAIL_BCC"),
    }

