def get_ai_config(task_ai_config: dict) -> dict:
    """Build AI analysis configuration, resolving provider-specific settings."""

    provider = task_ai_config.get("provider", "lmstudio").lower()

    config = {
        "enabled": task_ai_config.get("enabled", False),
        "run_after_predefined": task_ai_config.get("run_after_predefined", True),
        "sample_size": task_ai_config.get("sample_size", 50),
        "prompt_template": task_ai_config.get(
            "prompt_template",
            "Analyze this dataset for anomalies, suspicious patterns, or data quality issues. Return findings as a JSON list with fields: finding_type, description, severity (info/warning/critical), affected_columns."
        ),
        "details": task_ai_config.get("details", ""),
    }

    if provider == "openai":
        config["provider"] = "openai"
        config["model"] = task_ai_config.get(
            "model", os.getenv("AI_MODEL", "gpt-4o-mini")
        )
        config["api_key"] = os.getenv(task_ai_config.get("api_key_env", "OPENAI_API_KEY"))

    elif provider == "anthropic":
        config["provider"] = "anthropic"
        config["model"] = task_ai_config.get(
            "model", os.getenv("AI_MODEL", "claude-3-haiku-20240307")
        )
        config["api_key"] = os.getenv(task_ai_config.get("api_key_env", "ANTHROPIC_API_KEY"))

    elif provider == "lmstudio" or provider == "local":
        config["provider"] = "lmstudio"
        config["base_url"] = os.getenv(
            "LM_STUDIO_URL", "http://127.0.0.1:1234/v1"
        )
        config["api_key"] = os.getenv("LM_STUDIO_API_KEY", "lm-studio")
        config["model"] = task_ai_config.get(
            "model", os.getenv("LM_STUDIO_MODEL", "")
        )

    else:
        config["provider"] = provider

    return config
